package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_pow_TriageGen1Test {

    private static final double DELTA = 1e-15;



    @Test
    public void testPow_NaNAndInfinity() {
        // x is NaN
        assertTrue(Double.isNaN(FastMath.pow(Double.NaN, 2.0)));

        // x is Positive Infinity
        assertTrue(Double.isInfinite(FastMath.pow(Double.POSITIVE_INFINITY, 2.0)));
        assertEquals(0.0, FastMath.pow(Double.POSITIVE_INFINITY, -2.0), DELTA);
        assertTrue(Double.isNaN(FastMath.pow(Double.POSITIVE_INFINITY, Double.NaN)));

        // x is Negative Infinity
        assertTrue(Double.isNaN(FastMath.pow(Double.NEGATIVE_INFINITY, Double.NaN)));
        // y < 0 and y is odd integer
        assertEquals(-0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -3.0), DELTA);
        // y < 0 and y is even integer
        assertEquals(0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -2.0), DELTA);
        // y < 0 and y is not an integer
        assertEquals(0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -2.5), DELTA);
        // y > 0 and y is odd integer
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 3.0), DELTA);
        // y > 0 and y is even integer
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 2.0), DELTA);
        // y > 0 and y is not an integer
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 2.5), DELTA);

        // y is Positive Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.POSITIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.POSITIVE_INFINITY)));
        assertTrue(Double.isInfinite(FastMath.pow(2.0, Double.POSITIVE_INFINITY)));
        assertEquals(0.0, FastMath.pow(0.5, Double.POSITIVE_INFINITY), DELTA);

        // y is Negative Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.NEGATIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.NEGATIVE_INFINITY)));
        assertTrue(Double.isInfinite(FastMath.pow(0.5, Double.NEGATIVE_INFINITY)));
        assertEquals(0.0, FastMath.pow(2.0, Double.NEGATIVE_INFINITY), DELTA);
    }








}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_pow_TriageGen1Test {

    private static final double DELTA = 1e-15;





    @Test
    public void testPow_ZeroCases() {
        // x is 0.0
        assertEquals(0.0, FastMath.pow(0.0, 2.0), DELTA);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.0, -2.0), DELTA);

        // x is -0.0
        // y < 0 and y is odd integer -> -Infinity
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(-0.0, -3.0), DELTA);
        // y > 0 and y is odd integer -> -0.0
        assertEquals(-0.0, FastMath.pow(-0.0, 3.0), DELTA);
        // y is not integer -> check path
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(-0.0, -2.5), DELTA);
    }






}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_pow_TriageGen1Test {

    private static final double DELTA = 1e-15;







    @Test
    public void testPow_NegativeX() {
        // x < 0, y is even integer
        assertEquals(4.0, FastMath.pow(-2.0, 2.0), DELTA);
        // x < 0, y is odd integer
        assertEquals(-8.0, FastMath.pow(-2.0, 3.0), DELTA);
        // x < 0, y is non-integer
        assertTrue(Double.isNaN(FastMath.pow(-2.0, 2.5)));
        // x < 0, y is very large (hits the TWO_POWER_52 branch)
        double largeY = Math.pow(2, 53);
        assertFalse(Double.isNaN(FastMath.pow(-2.0, largeY)));
    }




}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_pow_TriageGen1Test {

    private static final double DELTA = 1e-15;









    @Test
    public void testPow_LargeY() {
        // Tests the branch where y is outside [-8e298, 8e298]
        double hugeY = 1e300;
        // Since x > 1, result will be Infinity
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(2.0, hugeY), DELTA);
        // Since x < 1, result will be 0
        assertEquals(0.0, FastMath.pow(0.5, hugeY), DELTA);
    }


}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_pow_TriageGen1Test {

    private static final double DELTA = 1e-15;











    @Test
    public void testPow_ComplexCalculations() {
        // General case for the log/exp logic
        assertEquals(Math.pow(2.718281828459, 2.0), FastMath.pow(2.718281828459, 2.0), 1e-10);
        assertEquals(Math.pow(3.0, 4.5), FastMath.pow(3.0, 4.5), 1e-10);
        assertEquals(Math.pow(0.1, 0.1), FastMath.pow(0.1, 0.1), 1e-10);
    }
}
